-- P06 service command API: complete version payloads, immutable history,
-- fail-closed tenant authorization and bounded dependency impact simulation.

create function private.is_valid_service_fulfillment_config(p_value jsonb) returns boolean
language sql immutable security definer set search_path=pg_catalog as $$
 select p_value is not null and jsonb_typeof(p_value)='object'
  and octet_length(convert_to(p_value::text,'UTF8'))<=100000
  and p_value?'schema_version' and jsonb_typeof(p_value->'schema_version')='number' and p_value->>'schema_version'='1'
  and not exists(select 1 from jsonb_object_keys(p_value) k where k not in(
   'schema_version','deliverables','exclusions','acceptance_criteria','required_evidence','correction_rules',
   'client_documents','provider_documents','qualification_rules','matching_rules','quote_template','required_for_quote',
   'default_sla','clauses','incident_rules','plan_availability','box_availability','credit_cost_minor',
   'provider_costs_minor','sku_codes','volume_contract_codes','standard_deliverables_fr','standard_proof_fr'))
  and not exists(select 1 from jsonb_each(p_value) e where e.key in(
   'deliverables','exclusions','acceptance_criteria','required_evidence','client_documents','provider_documents',
   'required_for_quote','clauses','plan_availability','box_availability','sku_codes','volume_contract_codes') and jsonb_typeof(e.value)<>'array')
  and not exists(select 1 from jsonb_each(p_value) e where e.key in(
   'correction_rules','qualification_rules','matching_rules','quote_template','default_sla','incident_rules','provider_costs_minor') and jsonb_typeof(e.value)<>'object')
  and (not(p_value?'credit_cost_minor') or(jsonb_typeof(p_value->'credit_cost_minor')='number' and(p_value->>'credit_cost_minor')~'^(0|[1-9][0-9]{0,17})$'))
  and not exists(select 1 from jsonb_each(p_value) e where e.key in('standard_deliverables_fr','standard_proof_fr') and jsonb_typeof(e.value) not in('string','null'))
  and not exists(select 1 from jsonb_each(coalesce(p_value->'provider_costs_minor','{}'::jsonb)) e where jsonb_typeof(e.value)<>'number' or e.value::text!~'^(0|[1-9][0-9]{0,17})$')
  and not exists(select 1 from jsonb_each(p_value) e cross join lateral jsonb_array_elements(case when jsonb_typeof(e.value)='array'then e.value else'[]'::jsonb end) a where e.key in(
   'deliverables','exclusions','acceptance_criteria','required_evidence','client_documents','provider_documents',
   'required_for_quote','clauses','plan_availability','box_availability','sku_codes','volume_contract_codes')
   and(jsonb_typeof(a)<>'string' or length(btrim(a#>>'{}')) not between 1 and 500))
$$;

create function private.normalize_service_fulfillment_config(p_value jsonb) returns jsonb
language plpgsql immutable security definer set search_path=pg_catalog,private as $$
declare v_value jsonb;
begin
 v_value:=case when jsonb_typeof(p_value)='object' and not(p_value?'schema_version') then p_value||'{"schema_version":1}'::jsonb else p_value end;
 if not private.is_valid_service_fulfillment_config(v_value) then raise exception 'CATALOG_SERVICE_CONFIG_SCHEMA_INVALID' using errcode='22023';end if;
 return v_value;
end $$;

create function private.normalize_service_visibility_rules(p_value jsonb) returns jsonb
language plpgsql immutable security definer set search_path=pg_catalog,private as $$
declare v_value jsonb;
begin
 v_value:=case when jsonb_typeof(p_value)='object' and not(p_value?'schema_version') then p_value||'{"schema_version":1}'::jsonb else p_value end;
 if not private.is_valid_service_visibility_rules(v_value) then raise exception 'CATALOG_SERVICE_CONFIG_SCHEMA_INVALID' using errcode='22023';end if;
 return v_value;
end $$;

create function private.is_valid_service_visibility_rules(p_value jsonb) returns boolean
language sql immutable security definer set search_path=pg_catalog as $$
 select p_value is not null and jsonb_typeof(p_value)='object'
  and octet_length(convert_to(p_value::text,'UTF8'))<=20000
  and p_value?'schema_version' and jsonb_typeof(p_value->'schema_version')='number' and p_value->>'schema_version'='1'
  and not exists(select 1 from jsonb_object_keys(p_value) k where k not in('schema_version','segments','plans','organization_ids','regions','client_types'))
  and not exists(select 1 from jsonb_each(p_value) e where e.key<>'schema_version' and jsonb_typeof(e.value)<>'array')
  and not exists(select 1 from jsonb_each(p_value) e cross join lateral jsonb_array_elements(case when jsonb_typeof(e.value)='array'then e.value else'[]'::jsonb end) a where e.key<>'schema_version' and(jsonb_typeof(a)<>'string' or length(btrim(a#>>'{}')) not between 1 and 200))
$$;

create function private.assert_catalog_service_payload(
 p_primary_subcategory_id uuid,p_code text,p_slug text,p_name_fr text,p_name_ar text,
 p_short_description_fr text,p_short_description_ar text,p_long_description_fr text,p_long_description_ar text,
 p_service_type text,p_unit_label_fr text,p_unit_label_ar text,p_credit_eligible boolean,p_volume_eligible boolean,
 p_recurring_eligible boolean,p_trial_eligible boolean,p_rfq_required boolean,p_fixed_fulfillment_allowed boolean,
 p_base_currency text,p_sort_order integer,p_fulfillment_config jsonb,p_visibility_rules jsonb,p_sensitive boolean,p_change_reason text
) returns void language plpgsql immutable security definer set search_path=pg_catalog as $$
begin
 if p_primary_subcategory_id is null or btrim(coalesce(p_code,''))!~'^[A-Z][A-Z0-9_-]{1,79}$'
  or btrim(coalesce(p_slug,''))!~'^[a-z0-9]+(?:-[a-z0-9]+)*$'
  or length(btrim(coalesce(p_name_fr,''))) not between 2 and 240 or length(btrim(coalesce(p_name_ar,''))) not between 2 and 240
  or length(btrim(coalesce(p_short_description_fr,''))) not between 3 and 1000 or length(btrim(coalesce(p_short_description_ar,''))) not between 3 and 1000
  or length(btrim(coalesce(p_long_description_fr,''))) not between 3 and 8000 or length(btrim(coalesce(p_long_description_ar,''))) not between 3 and 8000
  or btrim(coalesce(p_service_type,''))!~'^[A-Z][A-Z0-9_]{1,79}$'
  or length(btrim(coalesce(p_unit_label_fr,''))) not between 1 and 120 or length(btrim(coalesce(p_unit_label_ar,''))) not between 1 and 120
  or p_credit_eligible is null or p_volume_eligible is null or p_recurring_eligible is null or p_trial_eligible is null
  or p_rfq_required is null or p_fixed_fulfillment_allowed is null or p_sensitive is null
  or btrim(coalesce(p_base_currency,''))!~'^[A-Z]{3}$' or p_sort_order is null or p_sort_order<1
  or not private.is_valid_service_fulfillment_config(p_fulfillment_config)
  or not private.is_valid_service_visibility_rules(p_visibility_rules)
  or length(btrim(coalesce(p_change_reason,''))) not between 3 and 500 then
  raise exception 'INVALID_CATALOG_SERVICE' using errcode='22023';
 end if;
end $$;

create function private.catalog_service_payload_hash(
 p_primary_subcategory_id uuid,p_code text,p_slug text,p_name_fr text,p_name_ar text,
 p_short_description_fr text,p_short_description_ar text,p_long_description_fr text,p_long_description_ar text,
 p_service_type text,p_unit_label_fr text,p_unit_label_ar text,p_credit_eligible boolean,p_volume_eligible boolean,
 p_recurring_eligible boolean,p_trial_eligible boolean,p_rfq_required boolean,p_fixed_fulfillment_allowed boolean,
 p_base_currency text,p_sort_order integer,p_fulfillment_config jsonb,p_visibility_rules jsonb,p_sensitive boolean
) returns text language sql immutable security definer set search_path=pg_catalog,private as $$
 select private.canonical_request_hash(jsonb_build_object(
  'primary_subcategory_id',p_primary_subcategory_id,'code',btrim(p_code),'slug',btrim(p_slug),
  'name_fr',btrim(p_name_fr),'name_ar',btrim(p_name_ar),'short_description_fr',btrim(p_short_description_fr),
  'short_description_ar',btrim(p_short_description_ar),'long_description_fr',btrim(p_long_description_fr),
  'long_description_ar',btrim(p_long_description_ar),'service_type',btrim(p_service_type),
  'unit_label_fr',btrim(p_unit_label_fr),'unit_label_ar',btrim(p_unit_label_ar),
  'credit_eligible',p_credit_eligible,'volume_eligible',p_volume_eligible,'recurring_eligible',p_recurring_eligible,
  'trial_eligible',p_trial_eligible,'rfq_required',p_rfq_required,'fixed_fulfillment_allowed',p_fixed_fulfillment_allowed,
  'base_currency',btrim(p_base_currency),'sort_order',p_sort_order,'fulfillment_config',p_fulfillment_config,
  'visibility_rules',p_visibility_rules,'sensitive',p_sensitive))
$$;

create function private.catalog_service_impact_snapshot(p_service_id uuid,p_max_items integer)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare v_service public.catalog_services%rowtype;v_release_count bigint;v_change_count bigint;v_questionnaire_count bigint;v_question_count bigint;v_link_count bigint;v_blocking jsonb:='[]'::jsonb;v_dependencies jsonb;v_truncated boolean;
begin
 if p_service_id is null or p_max_items is null or p_max_items not between 1 and 100 then raise exception 'INVALID_CATALOG_IMPACT_REQUEST' using errcode='22023';end if;
 select * into v_service from public.catalog_services where id=p_service_id;if not found then raise exception 'CATALOG_SERVICE_NOT_FOUND' using errcode='P0002';end if;
 select count(*) into v_release_count from public.catalog_release_items i join public.catalog_releases r on r.id=i.release_id and r.library_id=i.library_id
  where i.object_type='SERVICE' and i.object_id=p_service_id and(r.status in('SCHEDULED','PUBLISHING')or(r.status='PUBLISHED'and(r.effective_until is null or statement_timestamp()<r.effective_until)));
 select count(*) into v_change_count from public.catalog_change_requests c where c.target_type='SERVICE' and c.target_id=p_service_id and c.status='IN_REVIEW';
 select count(distinct qv.id) into v_question_count from public.question_versions qv where qv.source_service_id=p_service_id and qv.status<>'ARCHIVED';
 select count(distinct qnv.id) into v_questionnaire_count from public.question_versions qv join public.questionnaire_version_questions qvq on qvq.question_version_id=qv.id join public.questionnaire_versions qnv on qnv.id=qvq.questionnaire_version_id
  where qv.source_service_id=p_service_id and qnv.status in ('FRANCHISE_REVIEW','CENTRAL_REVIEW','APPROVED','SCHEDULED','PUBLISHED');
 select count(*) into v_link_count from public.catalog_service_subcategory_links l where l.service_id=p_service_id and l.status not in ('RETIRED','ARCHIVED');
 if v_release_count>0 then v_blocking:=v_blocking||jsonb_build_array(jsonb_build_object('dependency_type','ACTIVE_CATALOG_RELEASE','count',v_release_count,'sample_ids',(select coalesce(jsonb_agg(x.id order by x.id::text),'[]'::jsonb) from(select distinct r.id from public.catalog_release_items i join public.catalog_releases r on r.id=i.release_id and r.library_id=i.library_id where i.object_type='SERVICE' and i.object_id=p_service_id and(r.status in('SCHEDULED','PUBLISHING')or(r.status='PUBLISHED'and(r.effective_until is null or statement_timestamp()<r.effective_until)))order by r.id limit p_max_items)x)));end if;
 if v_change_count>0 then v_blocking:=v_blocking||jsonb_build_array(jsonb_build_object('dependency_type','OPEN_CHANGE_REQUEST','count',v_change_count,'sample_ids',(select coalesce(jsonb_agg(x.id order by x.id::text),'[]'::jsonb) from(select c.id from public.catalog_change_requests c where c.target_type='SERVICE' and c.target_id=p_service_id and c.status='IN_REVIEW' order by c.id::text limit p_max_items)x)));end if;
 if v_questionnaire_count>0 then v_blocking:=v_blocking||jsonb_build_array(jsonb_build_object('dependency_type','ACTIVE_QUESTIONNAIRE_VERSION','count',v_questionnaire_count,'sample_ids',(select coalesce(jsonb_agg(x.id order by x.id::text),'[]'::jsonb) from(select distinct qnv.id from public.question_versions qv join public.questionnaire_version_questions qvq on qvq.question_version_id=qv.id join public.questionnaire_versions qnv on qnv.id=qvq.questionnaire_version_id where qv.source_service_id=p_service_id and qnv.status in ('FRANCHISE_REVIEW','CENTRAL_REVIEW','APPROVED','SCHEDULED','PUBLISHED') order by qnv.id::text limit p_max_items)x)));end if;
 v_truncated:=v_release_count>p_max_items or v_change_count>p_max_items or v_questionnaire_count>p_max_items or v_question_count>p_max_items or v_link_count>p_max_items;
 v_dependencies:=jsonb_build_array(
  jsonb_build_object('dependency_type','ACTIVE_CATALOG_RELEASE','count',v_release_count,'blocking',true),
  jsonb_build_object('dependency_type','OPEN_CHANGE_REQUEST','count',v_change_count,'blocking',true),
  jsonb_build_object('dependency_type','ACTIVE_QUESTIONNAIRE_VERSION','count',v_questionnaire_count,'blocking',true),
  jsonb_build_object('dependency_type','CATALOG_QUESTION_VERSION','count',v_question_count,'blocking',false),
  jsonb_build_object('dependency_type','ACTIVE_SUBCATEGORY_LINK','count',v_link_count,'blocking',false));
 return jsonb_build_object('service_id',p_service_id,'library_id',v_service.library_id,'bounded',true,'max_items',p_max_items,'truncated',v_truncated,'can_archive_immediately',jsonb_array_length(v_blocking)=0,'blocking_dependencies',v_blocking,'dependencies',v_dependencies);
end $$;

create function private.guard_catalog_service_dependency() returns trigger
language plpgsql security definer set search_path=pg_catalog as $$
declare v_service_id uuid;v_release_id uuid;v_status text;v_effective_until timestamptz;v_row record;
begin
 if tg_table_name='catalog_release_items' then
  if coalesce(new.object_type,old.object_type)='SERVICE' then
   v_service_id:=coalesce(new.object_id,old.object_id);
   perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_service_id::text,0));
   if tg_op<>'DELETE' then select status,effective_until into v_status,v_effective_until from public.catalog_releases where id=new.release_id;
    if(v_status in('SCHEDULED','PUBLISHING')or(v_status='PUBLISHED'and(v_effective_until is null or statement_timestamp()<v_effective_until)))and exists(select 1 from public.catalog_services where id=v_service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;
   end if;
  end if;
 elsif tg_table_name='catalog_releases' then
  v_release_id:=coalesce(new.id,old.id);
  for v_row in select object_id service_id from public.catalog_release_items where release_id=v_release_id and object_type='SERVICE' order by object_id loop
   perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_row.service_id::text,0));
   if tg_op<>'DELETE'and(new.status in('SCHEDULED','PUBLISHING')or(new.status='PUBLISHED'and(new.effective_until is null or statement_timestamp()<new.effective_until)))and exists(select 1 from public.catalog_services where id=v_row.service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;
  end loop;
 elsif tg_table_name='catalog_change_requests' then
  if coalesce(new.target_type,old.target_type)='SERVICE' then v_service_id:=coalesce(new.target_id,old.target_id);perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_service_id::text,0));if tg_op<>'DELETE'and new.status='IN_REVIEW'and exists(select 1 from public.catalog_services where id=v_service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;end if;
 elsif tg_table_name='question_versions' then
  v_service_id:=coalesce(new.source_service_id,old.source_service_id);if v_service_id is not null then perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_service_id::text,0));if tg_op<>'DELETE'and new.status<>'ARCHIVED'and exists(select 1 from public.catalog_services where id=v_service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;end if;
 elsif tg_table_name='questionnaire_version_questions' then
  select source_service_id into v_service_id from public.question_versions where id=coalesce(new.question_version_id,old.question_version_id);if v_service_id is not null then perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_service_id::text,0));if tg_op<>'DELETE'and exists(select 1 from public.questionnaire_versions q where q.id=new.questionnaire_version_id and q.status in('FRANCHISE_REVIEW','CENTRAL_REVIEW','APPROVED','SCHEDULED','PUBLISHED'))and exists(select 1 from public.catalog_services where id=v_service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;end if;
 elsif tg_table_name='questionnaire_versions' then
  for v_row in select distinct qv.source_service_id service_id from public.questionnaire_version_questions x join public.question_versions qv on qv.id=x.question_version_id where x.questionnaire_version_id=coalesce(new.id,old.id)and qv.source_service_id is not null order by qv.source_service_id loop
   perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||v_row.service_id::text,0));if tg_op<>'DELETE'and new.status in('FRANCHISE_REVIEW','CENTRAL_REVIEW','APPROVED','SCHEDULED','PUBLISHED')and exists(select 1 from public.catalog_services where id=v_row.service_id and status='ARCHIVED')then raise exception 'CATALOG_SERVICE_DEPENDENCY_REJECTED' using errcode='55000';end if;
  end loop;
 end if;
 return case when tg_op='DELETE'then old else new end;
end $$;

revoke all on function private.guard_catalog_service_dependency() from public,anon,authenticated,service_role;
create trigger catalog_release_items_service_dependency_guard before insert or update or delete on public.catalog_release_items for each row execute function private.guard_catalog_service_dependency();
create trigger catalog_releases_service_dependency_guard before insert or update or delete on public.catalog_releases for each row execute function private.guard_catalog_service_dependency();
create trigger catalog_changes_service_dependency_guard before insert or update or delete on public.catalog_change_requests for each row execute function private.guard_catalog_service_dependency();
create trigger question_versions_service_dependency_guard before insert or update or delete on public.question_versions for each row execute function private.guard_catalog_service_dependency();
create trigger questionnaire_questions_service_dependency_guard before insert or update or delete on public.questionnaire_version_questions for each row execute function private.guard_catalog_service_dependency();
create trigger questionnaire_versions_service_dependency_guard before insert or update or delete on public.questionnaire_versions for each row execute function private.guard_catalog_service_dependency();

revoke all on function private.is_valid_service_fulfillment_config(jsonb),private.is_valid_service_visibility_rules(jsonb),private.normalize_service_fulfillment_config(jsonb),private.normalize_service_visibility_rules(jsonb),private.assert_catalog_service_payload(uuid,text,text,text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,text,integer,jsonb,jsonb,boolean,text),private.catalog_service_payload_hash(uuid,text,text,text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,text,integer,jsonb,jsonb,boolean),private.catalog_service_impact_snapshot(uuid,integer) from public,anon,authenticated,service_role;

create function public.create_catalog_service(
 p_library_id uuid,p_primary_subcategory_id uuid,p_code text,p_slug text,p_name_fr text,p_name_ar text,
 p_short_description_fr text,p_short_description_ar text,p_long_description_fr text,p_long_description_ar text,
 p_service_type text,p_unit_label_fr text,p_unit_label_ar text,p_credit_eligible boolean,p_volume_eligible boolean,
 p_recurring_eligible boolean,p_trial_eligible boolean,p_rfq_required boolean,p_fixed_fulfillment_allowed boolean,
 p_base_currency text,p_sort_order integer,p_fulfillment_config jsonb,p_visibility_rules jsonb,p_sensitive boolean,
 p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid()
) returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_parent public.catalog_subcategories%rowtype;v_org uuid;v_hash text;v_content_hash text;v_command uuid;v_replay jsonb;v_service uuid;v_version uuid;v_link uuid;v_link_version uuid;v_link_hash text;v_response jsonb;
begin
 perform private.assert_catalog_service_payload(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,p_short_description_fr,p_short_description_ar,p_long_description_fr,p_long_description_ar,p_service_type,p_unit_label_fr,p_unit_label_ar,p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,p_base_currency,p_sort_order,p_fulfillment_config,p_visibility_rules,p_sensitive,p_change_reason);
 if v_actor is null or not private.has_library_permission(p_library_id,'CATALOG_EDIT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;
 if p_sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.create.v1','library_id',p_library_id,'primary_subcategory_id',p_primary_subcategory_id,'code',btrim(p_code),'slug',btrim(p_slug),'name_fr',btrim(p_name_fr),'name_ar',btrim(p_name_ar),'short_description_fr',btrim(p_short_description_fr),'short_description_ar',btrim(p_short_description_ar),'long_description_fr',btrim(p_long_description_fr),'long_description_ar',btrim(p_long_description_ar),'service_type',btrim(p_service_type),'unit_label_fr',btrim(p_unit_label_fr),'unit_label_ar',btrim(p_unit_label_ar),'credit_eligible',p_credit_eligible,'volume_eligible',p_volume_eligible,'recurring_eligible',p_recurring_eligible,'trial_eligible',p_trial_eligible,'rfq_required',p_rfq_required,'fixed_fulfillment_allowed',p_fixed_fulfillment_allowed,'base_currency',btrim(p_base_currency),'sort_order',p_sort_order,'fulfillment_config',p_fulfillment_config,'visibility_rules',p_visibility_rules,'sensitive',p_sensitive,'change_reason',btrim(p_change_reason)));
 select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.create',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-library:'||p_library_id::text,0));
 perform private.assert_catalog_permission_locked(p_library_id,'CATALOG_EDIT',v_actor);if p_sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;if v_replay is not null then return v_replay;end if;
 select * into v_parent from public.catalog_subcategories where id=p_primary_subcategory_id and library_id=p_library_id and status not in ('RETIRED','ARCHIVED') for share;if not found then raise exception 'CATALOG_PARENT_SCOPE_MISMATCH' using errcode='23514';end if;
 select steward_organization_id into v_org from public.catalog_libraries where id=p_library_id;
 v_content_hash:=private.catalog_service_payload_hash(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,p_short_description_fr,p_short_description_ar,p_long_description_fr,p_long_description_ar,p_service_type,p_unit_label_fr,p_unit_label_ar,p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,p_base_currency,p_sort_order,p_fulfillment_config,p_visibility_rules,p_sensitive);
 insert into public.catalog_services(library_id,primary_subcategory_id,code,slug,status,created_by) values(p_library_id,p_primary_subcategory_id,btrim(p_code),btrim(p_slug),'DRAFT',v_actor) returning id into v_service;
 insert into public.catalog_service_versions(service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,credit_eligible,volume_eligible,recurring_eligible,trial_eligible,rfq_required,fixed_fulfillment_allowed,base_currency,sort_order,fulfillment_config,visibility_rules,change_reason,content_hash,sensitive,translation_review_status,created_by,primary_subcategory_id,code,slug)
 values(v_service,p_library_id,1,'DRAFT',btrim(p_name_fr),btrim(p_name_ar),btrim(p_short_description_fr),btrim(p_short_description_ar),btrim(p_long_description_fr),btrim(p_long_description_ar),btrim(p_service_type),btrim(p_unit_label_fr),btrim(p_unit_label_ar),p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,btrim(p_base_currency),p_sort_order,p_fulfillment_config,p_visibility_rules,btrim(p_change_reason),v_content_hash,p_sensitive,'PENDING',v_actor,p_primary_subcategory_id,btrim(p_code),btrim(p_slug)) returning id into v_version;
 update public.catalog_services set current_draft_version_id=v_version where id=v_service;
 v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',v_service,'subcategory_id',p_primary_subcategory_id,'link_type','PRIMARY'));
 insert into public.catalog_service_subcategory_links(service_id,subcategory_id,library_id,link_type,status,created_by) values(v_service,p_primary_subcategory_id,p_library_id,'PRIMARY','DRAFT',v_actor) returning id into v_link;
 insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_link,p_library_id,1,'DRAFT',btrim(p_change_reason),v_link_hash,v_actor,v_service,p_primary_subcategory_id,'PRIMARY') returning id into v_link_version;
 update public.catalog_service_subcategory_links set current_version_id=v_link_version where id=v_link;
 v_response:=jsonb_build_object('outcome','CATALOG_SERVICE_CREATED','service_id',v_service,'library_id',p_library_id,'version_id',v_version,'primary_link_id',v_link,'primary_link_version_id',v_link_version,'identity_row_version',1,'version_row_version',1,'content_hash',v_content_hash,'command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash) values(v_org,v_actor,'USER','catalog.service.created','catalog_service',v_service::text,p_correlation_id,jsonb_build_object('library_id',p_library_id,'version_id',v_version,'primary_link_id',v_link,'command_id',v_command),null,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,causation_id) values(v_org,'catalog_service',v_service::text,'CatalogServiceCreatedV1',p_correlation_id,jsonb_build_object('service_id',v_service,'library_id',p_library_id,'version_id',v_version,'primary_subcategory_id',p_primary_subcategory_id),p_idempotency_key,v_command);
 perform private.finish_catalog_command(v_actor,'catalog.service.create',p_idempotency_key,v_response);return v_response;
end $$;

create function public.save_catalog_service_draft(
 p_service_id uuid,p_version_id uuid,p_primary_subcategory_id uuid,p_code text,p_slug text,p_name_fr text,p_name_ar text,
 p_short_description_fr text,p_short_description_ar text,p_long_description_fr text,p_long_description_ar text,
 p_service_type text,p_unit_label_fr text,p_unit_label_ar text,p_credit_eligible boolean,p_volume_eligible boolean,
 p_recurring_eligible boolean,p_trial_eligible boolean,p_rfq_required boolean,p_fixed_fulfillment_allowed boolean,
 p_base_currency text,p_sort_order integer,p_fulfillment_config jsonb,p_visibility_rules jsonb,p_sensitive boolean,p_change_reason text,
 p_expected_identity_row_version integer,p_expected_version_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid()
) returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_identity public.catalog_services%rowtype;v_old public.catalog_service_versions%rowtype;v_parent public.catalog_subcategories%rowtype;v_org uuid;v_hash text;v_content_hash text;v_command uuid;v_replay jsonb;v_new_version uuid;v_number integer;v_new_version_row integer;v_old_link public.catalog_service_subcategory_links%rowtype;v_link uuid;v_link_version uuid;v_link_number integer;v_link_hash text;v_response jsonb;
begin
 perform private.assert_catalog_service_payload(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,p_short_description_fr,p_short_description_ar,p_long_description_fr,p_long_description_ar,p_service_type,p_unit_label_fr,p_unit_label_ar,p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,p_base_currency,p_sort_order,p_fulfillment_config,p_visibility_rules,p_sensitive,p_change_reason);
 if p_expected_identity_row_version is null or p_expected_identity_row_version<1 or p_expected_version_row_version is null or p_expected_version_row_version<1 then raise exception 'INVALID_CATALOG_VERSION' using errcode='22023';end if;
 if v_actor is null then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;select * into v_identity from public.catalog_services where id=p_service_id;if not found or not private.has_library_permission(v_identity.library_id,'CATALOG_EDIT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;
 if p_sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.save.v1','service_id',p_service_id,'version_id',p_version_id,'primary_subcategory_id',p_primary_subcategory_id,'code',btrim(p_code),'slug',btrim(p_slug),'name_fr',btrim(p_name_fr),'name_ar',btrim(p_name_ar),'short_description_fr',btrim(p_short_description_fr),'short_description_ar',btrim(p_short_description_ar),'long_description_fr',btrim(p_long_description_fr),'long_description_ar',btrim(p_long_description_ar),'service_type',btrim(p_service_type),'unit_label_fr',btrim(p_unit_label_fr),'unit_label_ar',btrim(p_unit_label_ar),'credit_eligible',p_credit_eligible,'volume_eligible',p_volume_eligible,'recurring_eligible',p_recurring_eligible,'trial_eligible',p_trial_eligible,'rfq_required',p_rfq_required,'fixed_fulfillment_allowed',p_fixed_fulfillment_allowed,'base_currency',btrim(p_base_currency),'sort_order',p_sort_order,'fulfillment_config',p_fulfillment_config,'visibility_rules',p_visibility_rules,'sensitive',p_sensitive,'change_reason',btrim(p_change_reason),'expected_identity',p_expected_identity_row_version,'expected_version',p_expected_version_row_version));
 select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.save',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-service:'||p_service_id::text,0));select * into v_identity from public.catalog_services where id=p_service_id for update;select * into v_old from public.catalog_service_versions where id=p_version_id and service_id=p_service_id for update;if not found then raise exception 'CATALOG_VERSION_NOT_FOUND' using errcode='P0002';end if;
 perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_EDIT',v_actor);if (p_sensitive or v_old.sensitive) and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;if v_replay is not null then return v_replay;end if;
 if v_identity.status='ARCHIVED' then raise exception 'CATALOG_SERVICE_ARCHIVED' using errcode='55000';end if;if p_version_id is distinct from coalesce(v_identity.current_draft_version_id,v_identity.current_published_version_id) then raise exception 'CATALOG_VERSION_NOT_CURRENT' using errcode='55000';end if;
 if v_identity.row_version is distinct from p_expected_identity_row_version or v_old.row_version is distinct from p_expected_version_row_version then raise exception 'STALE_CATALOG_VERSION' using errcode='40001';end if;
 select * into v_parent from public.catalog_subcategories where id=p_primary_subcategory_id and library_id=v_identity.library_id and status not in ('RETIRED','ARCHIVED') for share;if not found then raise exception 'CATALOG_PARENT_SCOPE_MISMATCH' using errcode='23514';end if;
 select steward_organization_id into v_org from public.catalog_libraries where id=v_identity.library_id;
 v_content_hash:=private.catalog_service_payload_hash(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,p_short_description_fr,p_short_description_ar,p_long_description_fr,p_long_description_ar,p_service_type,p_unit_label_fr,p_unit_label_ar,p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,p_base_currency,p_sort_order,p_fulfillment_config,p_visibility_rules,p_sensitive);
 if v_old.status='DRAFT' and v_old.translation_review_status<>'APPROVED' then
  update public.catalog_service_versions set primary_subcategory_id=p_primary_subcategory_id,code=btrim(p_code),slug=btrim(p_slug),name_fr=btrim(p_name_fr),name_ar=btrim(p_name_ar),short_description_fr=btrim(p_short_description_fr),short_description_ar=btrim(p_short_description_ar),long_description_fr=btrim(p_long_description_fr),long_description_ar=btrim(p_long_description_ar),service_type=btrim(p_service_type),unit_label_fr=btrim(p_unit_label_fr),unit_label_ar=btrim(p_unit_label_ar),credit_eligible=p_credit_eligible,volume_eligible=p_volume_eligible,recurring_eligible=p_recurring_eligible,trial_eligible=p_trial_eligible,rfq_required=p_rfq_required,fixed_fulfillment_allowed=p_fixed_fulfillment_allowed,base_currency=btrim(p_base_currency),sort_order=p_sort_order,fulfillment_config=p_fulfillment_config,visibility_rules=p_visibility_rules,change_reason=btrim(p_change_reason),content_hash=v_content_hash,sensitive=p_sensitive,translation_review_status='PENDING',translation_reviewer_user_id=null,translation_reviewed_at=null,translation_review_proof_hash=null,translation_review_version=0,row_version=row_version+1 where id=p_version_id returning id,row_version into v_new_version,v_new_version_row;
 else
  select coalesce(max(version),0)+1 into v_number from public.catalog_service_versions where service_id=p_service_id;
  insert into public.catalog_service_versions(service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,credit_eligible,volume_eligible,recurring_eligible,trial_eligible,rfq_required,fixed_fulfillment_allowed,base_currency,sort_order,fulfillment_config,visibility_rules,change_reason,content_hash,sensitive,translation_review_status,created_by,primary_subcategory_id,code,slug)
  values(p_service_id,v_identity.library_id,v_number,'DRAFT',btrim(p_name_fr),btrim(p_name_ar),btrim(p_short_description_fr),btrim(p_short_description_ar),btrim(p_long_description_fr),btrim(p_long_description_ar),btrim(p_service_type),btrim(p_unit_label_fr),btrim(p_unit_label_ar),p_credit_eligible,p_volume_eligible,p_recurring_eligible,p_trial_eligible,p_rfq_required,p_fixed_fulfillment_allowed,btrim(p_base_currency),p_sort_order,p_fulfillment_config,p_visibility_rules,btrim(p_change_reason),v_content_hash,p_sensitive,'PENDING',v_actor,p_primary_subcategory_id,btrim(p_code),btrim(p_slug)) returning id,row_version into v_new_version,v_new_version_row;
 end if;
 if v_identity.primary_subcategory_id is distinct from p_primary_subcategory_id then
  select * into v_old_link from public.catalog_service_subcategory_links where service_id=p_service_id and link_type='PRIMARY' and status not in ('RETIRED','ARCHIVED') for update;
  if found then select coalesce(max(version),0)+1 into v_link_number from public.catalog_service_subcategory_link_versions where link_id=v_old_link.id;v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',p_service_id,'subcategory_id',v_old_link.subcategory_id,'link_type','PRIMARY','status','ARCHIVED'));insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_old_link.id,v_identity.library_id,v_link_number,'ARCHIVED',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,v_old_link.subcategory_id,'PRIMARY') returning id into v_link_version;update public.catalog_service_subcategory_links set status='ARCHIVED',current_version_id=v_link_version,row_version=row_version+1 where id=v_old_link.id;end if;
  select * into v_old_link from public.catalog_service_subcategory_links where service_id=p_service_id and subcategory_id=p_primary_subcategory_id for update;
  v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',p_service_id,'subcategory_id',p_primary_subcategory_id,'link_type','PRIMARY'));
  if found then select coalesce(max(version),0)+1 into v_link_number from public.catalog_service_subcategory_link_versions where link_id=v_old_link.id;insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_old_link.id,v_identity.library_id,v_link_number,'DRAFT',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,p_primary_subcategory_id,'PRIMARY') returning id into v_link_version;update public.catalog_service_subcategory_links set link_type='PRIMARY',status='DRAFT',current_version_id=v_link_version,row_version=row_version+1 where id=v_old_link.id;v_link:=v_old_link.id;
  else insert into public.catalog_service_subcategory_links(service_id,subcategory_id,library_id,link_type,status,created_by) values(p_service_id,p_primary_subcategory_id,v_identity.library_id,'PRIMARY','DRAFT',v_actor) returning id into v_link;insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_link,v_identity.library_id,1,'DRAFT',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,p_primary_subcategory_id,'PRIMARY') returning id into v_link_version;update public.catalog_service_subcategory_links set current_version_id=v_link_version where id=v_link;end if;
 end if;
 update public.catalog_services set primary_subcategory_id=p_primary_subcategory_id,code=btrim(p_code),slug=btrim(p_slug),status=case when status='ARCHIVED'then'DRAFT'else status end,current_draft_version_id=v_new_version,archived_at=null,row_version=row_version+1 where id=p_service_id;
 v_response:=jsonb_build_object('outcome','CATALOG_SERVICE_DRAFT_SAVED','service_id',p_service_id,'library_id',v_identity.library_id,'version_id',v_new_version,'identity_row_version',p_expected_identity_row_version+1,'version_row_version',v_new_version_row,'content_hash',v_content_hash,'new_version',not(v_old.status='DRAFT' and v_old.translation_review_status<>'APPROVED'),'parent_changed',v_identity.primary_subcategory_id is distinct from p_primary_subcategory_id,'command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash) values(v_org,v_actor,'USER','catalog.service.draft_saved','catalog_service',p_service_id::text,p_correlation_id,jsonb_build_object('source_version_id',p_version_id,'version_id',v_new_version,'new_version',not(v_old.status='DRAFT' and v_old.translation_review_status<>'APPROVED'),'parent_changed',v_identity.primary_subcategory_id is distinct from p_primary_subcategory_id,'command_id',v_command),v_old.content_hash,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,causation_id) values(v_org,'catalog_service',p_service_id::text,'CatalogServiceDraftSavedV1',p_correlation_id,jsonb_build_object('service_id',p_service_id,'version_id',v_new_version,'primary_subcategory_id',p_primary_subcategory_id,'new_version',not(v_old.status='DRAFT' and v_old.translation_review_status<>'APPROVED')),p_idempotency_key,v_command);
 perform private.finish_catalog_command(v_actor,'catalog.service.save',p_idempotency_key,v_response);return v_response;
end $$;

create function public.duplicate_catalog_service(
 p_source_service_id uuid,p_source_version_id uuid,p_primary_subcategory_id uuid,p_code text,p_slug text,p_name_fr text,p_name_ar text,
 p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid()
) returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_source public.catalog_service_versions%rowtype;v_identity public.catalog_services%rowtype;v_parent public.catalog_subcategories%rowtype;v_org uuid;v_hash text;v_content_hash text;v_link_hash text;v_command uuid;v_replay jsonb;v_service uuid;v_version uuid;v_link uuid;v_link_version uuid;v_response jsonb;v_fulfillment jsonb;v_visibility jsonb;
begin
 if v_actor is null then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;select * into v_identity from public.catalog_services where id=p_source_service_id;if not found or not private.has_library_permission(v_identity.library_id,'CATALOG_EDIT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;
 select * into v_source from public.catalog_service_versions where id=p_source_version_id and service_id=p_source_service_id;if not found then raise exception 'CATALOG_VERSION_NOT_FOUND' using errcode='P0002';end if;
 v_fulfillment:=private.normalize_service_fulfillment_config(v_source.fulfillment_config);v_visibility:=private.normalize_service_visibility_rules(v_source.visibility_rules);
 perform private.assert_catalog_service_payload(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,v_source.short_description_fr,v_source.short_description_ar,v_source.long_description_fr,v_source.long_description_ar,v_source.service_type,v_source.unit_label_fr,v_source.unit_label_ar,v_source.credit_eligible,v_source.volume_eligible,v_source.recurring_eligible,v_source.trial_eligible,v_source.rfq_required,v_source.fixed_fulfillment_allowed,v_source.base_currency,v_source.sort_order,v_fulfillment,v_visibility,v_source.sensitive,p_change_reason);
 if v_actor is null or not private.has_library_permission(v_identity.library_id,'CATALOG_EDIT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;if v_source.sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.duplicate.v1','source_service_id',p_source_service_id,'source_version_id',p_source_version_id,'primary_subcategory_id',p_primary_subcategory_id,'code',btrim(p_code),'slug',btrim(p_slug),'name_fr',btrim(p_name_fr),'name_ar',btrim(p_name_ar),'change_reason',btrim(p_change_reason)));
 select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.duplicate',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-service:'||p_source_service_id::text,0));select * into v_identity from public.catalog_services where id=p_source_service_id for share;select * into v_source from public.catalog_service_versions where id=p_source_version_id and service_id=p_source_service_id for share;perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_EDIT',v_actor);if v_source.sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;if v_replay is not null then return v_replay;end if;select * into v_parent from public.catalog_subcategories where id=p_primary_subcategory_id and library_id=v_identity.library_id and status not in ('RETIRED','ARCHIVED') for share;if not found then raise exception 'CATALOG_PARENT_SCOPE_MISMATCH' using errcode='23514';end if;
 select steward_organization_id into v_org from public.catalog_libraries where id=v_identity.library_id;
 v_content_hash:=private.catalog_service_payload_hash(p_primary_subcategory_id,p_code,p_slug,p_name_fr,p_name_ar,v_source.short_description_fr,v_source.short_description_ar,v_source.long_description_fr,v_source.long_description_ar,v_source.service_type,v_source.unit_label_fr,v_source.unit_label_ar,v_source.credit_eligible,v_source.volume_eligible,v_source.recurring_eligible,v_source.trial_eligible,v_source.rfq_required,v_source.fixed_fulfillment_allowed,v_source.base_currency,v_source.sort_order,v_fulfillment,v_visibility,v_source.sensitive);
 insert into public.catalog_services(library_id,primary_subcategory_id,code,slug,status,created_by) values(v_identity.library_id,p_primary_subcategory_id,btrim(p_code),btrim(p_slug),'DRAFT',v_actor) returning id into v_service;
 insert into public.catalog_service_versions(service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,credit_eligible,volume_eligible,recurring_eligible,trial_eligible,rfq_required,fixed_fulfillment_allowed,base_currency,sort_order,fulfillment_config,visibility_rules,change_reason,content_hash,sensitive,translation_review_status,created_by,primary_subcategory_id,code,slug)
 values(v_service,v_identity.library_id,1,'DRAFT',btrim(p_name_fr),btrim(p_name_ar),v_source.short_description_fr,v_source.short_description_ar,v_source.long_description_fr,v_source.long_description_ar,v_source.service_type,v_source.unit_label_fr,v_source.unit_label_ar,v_source.credit_eligible,v_source.volume_eligible,v_source.recurring_eligible,v_source.trial_eligible,v_source.rfq_required,v_source.fixed_fulfillment_allowed,v_source.base_currency,v_source.sort_order,v_fulfillment,v_visibility,btrim(p_change_reason),v_content_hash,v_source.sensitive,'PENDING',v_actor,p_primary_subcategory_id,btrim(p_code),btrim(p_slug)) returning id into v_version;
 update public.catalog_services set current_draft_version_id=v_version where id=v_service;
 v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',v_service,'subcategory_id',p_primary_subcategory_id,'link_type','PRIMARY'));
 insert into public.catalog_service_subcategory_links(service_id,subcategory_id,library_id,link_type,status,created_by) values(v_service,p_primary_subcategory_id,v_identity.library_id,'PRIMARY','DRAFT',v_actor) returning id into v_link;
