create function public.simulate_catalog_service_impact(p_service_id uuid,p_max_items integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())
returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_service public.catalog_services%rowtype;v_org uuid;v_hash text;v_command uuid;v_replay jsonb;v_response jsonb;
begin
 if p_max_items is null or p_max_items not between 1 and 100 then raise exception 'INVALID_CATALOG_IMPACT_REQUEST' using errcode='22023';end if;
 if v_actor is null then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;select * into v_service from public.catalog_services where id=p_service_id;if not found or not private.has_library_permission(v_service.library_id,'CATALOG_VIEW_DRAFT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.impact.v1','service_id',p_service_id,'max_items',p_max_items));select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.impact',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock_shared(hashtextextended('catalog-service-dependency:'||p_service_id::text,0));perform pg_advisory_xact_lock(hashtextextended('catalog-service:'||p_service_id::text,0));select * into v_service from public.catalog_services where id=p_service_id for share;perform private.assert_catalog_permission_locked(v_service.library_id,'CATALOG_VIEW_DRAFT',v_actor);if v_replay is not null then return v_replay;end if;select steward_organization_id into v_org from public.catalog_libraries where id=v_service.library_id;
 v_response:=private.catalog_service_impact_snapshot(p_service_id,p_max_items)||jsonb_build_object('outcome','CATALOG_SERVICE_IMPACT_SIMULATED','command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash) values(v_org,v_actor,'USER','catalog.service.impact_simulated','catalog_service',p_service_id::text,p_correlation_id,jsonb_build_object('command_id',v_command,'max_items',p_max_items,'can_archive_immediately',v_response->'can_archive_immediately','blocking_dependency_count',jsonb_array_length(v_response->'blocking_dependencies')),null,repeat('0',64));
 perform private.finish_catalog_command(v_actor,'catalog.service.impact',p_idempotency_key,v_response);return v_response;
end $$;

create function public.archive_catalog_service(p_service_id uuid,p_version_id uuid,p_expected_identity_row_version integer,p_expected_version_row_version integer,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())
returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_identity public.catalog_services%rowtype;v_source public.catalog_service_versions%rowtype;v_org uuid;v_hash text;v_command uuid;v_replay jsonb;v_impact jsonb;v_number integer;v_version uuid;v_content_hash text;v_link record;v_link_number integer;v_link_version uuid;v_link_hash text;v_response jsonb;v_fulfillment jsonb;v_visibility jsonb;
begin
 if p_expected_identity_row_version is null or p_expected_identity_row_version<1 or p_expected_version_row_version is null or p_expected_version_row_version<1 or length(btrim(coalesce(p_change_reason,''))) not between 3 and 500 then raise exception 'INVALID_CATALOG_ARCHIVE' using errcode='22023';end if;
 if v_actor is null then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;select * into v_identity from public.catalog_services where id=p_service_id;if not found or not private.has_library_permission(v_identity.library_id,'CATALOG_EDIT',v_actor) then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;select * into v_source from public.catalog_service_versions where id=p_version_id and service_id=p_service_id;if not found then raise exception 'CATALOG_VERSION_NOT_FOUND' using errcode='P0002';end if;
 if v_source.sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.archive.v1','service_id',p_service_id,'version_id',p_version_id,'expected_identity',p_expected_identity_row_version,'expected_version',p_expected_version_row_version,'change_reason',btrim(p_change_reason)));select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.archive',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-service-dependency:'||p_service_id::text,0));perform pg_advisory_xact_lock(hashtextextended('catalog-service:'||p_service_id::text,0));select * into v_identity from public.catalog_services where id=p_service_id for update;select * into v_source from public.catalog_service_versions where id=p_version_id and service_id=p_service_id for update;perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_EDIT',v_actor);if v_source.sensitive and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;if v_replay is not null then return v_replay;end if;
 if v_identity.status='ARCHIVED' then raise exception 'CATALOG_SERVICE_ALREADY_ARCHIVED' using errcode='55000';end if;if p_version_id is distinct from coalesce(v_identity.current_draft_version_id,v_identity.current_published_version_id) then raise exception 'CATALOG_VERSION_NOT_CURRENT' using errcode='55000';end if;if v_identity.row_version is distinct from p_expected_identity_row_version or v_source.row_version is distinct from p_expected_version_row_version then raise exception 'STALE_CATALOG_VERSION' using errcode='40001';end if;
 v_impact:=private.catalog_service_impact_snapshot(p_service_id,25);if jsonb_array_length(v_impact->'blocking_dependencies')>0 then raise exception 'CATALOG_SERVICE_ARCHIVE_BLOCKED' using errcode='55000',detail=(v_impact->'blocking_dependencies')::text;end if;
 select steward_organization_id into v_org from public.catalog_libraries where id=v_identity.library_id;select coalesce(max(version),0)+1 into v_number from public.catalog_service_versions where service_id=p_service_id;
 v_fulfillment:=private.normalize_service_fulfillment_config(v_source.fulfillment_config);v_visibility:=private.normalize_service_visibility_rules(v_source.visibility_rules);v_content_hash:=private.canonical_request_hash(jsonb_build_object('restored_from_version_id',p_version_id,'archive_reason',btrim(p_change_reason),'source_content_hash',v_source.content_hash,'status','ARCHIVED','fulfillment_config',v_fulfillment,'visibility_rules',v_visibility));
 insert into public.catalog_service_versions(service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,credit_eligible,volume_eligible,recurring_eligible,trial_eligible,rfq_required,fixed_fulfillment_allowed,base_currency,sort_order,fulfillment_config,visibility_rules,change_reason,content_hash,sensitive,translation_review_status,created_by,primary_subcategory_id,code,slug)
 values(p_service_id,v_identity.library_id,v_number,'ARCHIVED',v_source.name_fr,v_source.name_ar,v_source.short_description_fr,v_source.short_description_ar,v_source.long_description_fr,v_source.long_description_ar,v_source.service_type,v_source.unit_label_fr,v_source.unit_label_ar,v_source.credit_eligible,v_source.volume_eligible,v_source.recurring_eligible,v_source.trial_eligible,v_source.rfq_required,v_source.fixed_fulfillment_allowed,v_source.base_currency,v_source.sort_order,v_fulfillment,v_visibility,btrim(p_change_reason),v_content_hash,v_source.sensitive,'PENDING',v_actor,v_source.primary_subcategory_id,v_source.code,v_source.slug) returning id into v_version;
 for v_link in select * from public.catalog_service_subcategory_links where service_id=p_service_id and status not in ('RETIRED','ARCHIVED') for update loop select coalesce(max(version),0)+1 into v_link_number from public.catalog_service_subcategory_link_versions where link_id=v_link.id;v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',p_service_id,'subcategory_id',v_link.subcategory_id,'link_type',v_link.link_type,'status','ARCHIVED'));insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_link.id,v_identity.library_id,v_link_number,'ARCHIVED',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,v_link.subcategory_id,v_link.link_type) returning id into v_link_version;update public.catalog_service_subcategory_links set status='ARCHIVED',current_version_id=v_link_version,row_version=row_version+1 where id=v_link.id;end loop;
 update public.catalog_services set status='ARCHIVED',current_draft_version_id=v_version,archived_at=clock_timestamp(),row_version=row_version+1 where id=p_service_id;
 v_response:=jsonb_build_object('outcome','CATALOG_SERVICE_ARCHIVED','service_id',p_service_id,'library_id',v_identity.library_id,'version_id',v_version,'identity_row_version',p_expected_identity_row_version+1,'version_row_version',1,'content_hash',v_content_hash,'blocking_dependencies','[]'::jsonb,'command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash) values(v_org,v_actor,'USER','catalog.service.archived','catalog_service',p_service_id::text,p_correlation_id,jsonb_build_object('source_version_id',p_version_id,'version_id',v_version,'command_id',v_command),v_source.content_hash,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,causation_id) values(v_org,'catalog_service',p_service_id::text,'CatalogServiceArchivedV1',p_correlation_id,jsonb_build_object('service_id',p_service_id,'version_id',v_version),p_idempotency_key,v_command);perform private.finish_catalog_command(v_actor,'catalog.service.archive',p_idempotency_key,v_response);return v_response;
end $$;

create function public.restore_catalog_service_version(p_service_id uuid,p_historical_version_id uuid,p_expected_identity_row_version integer,p_expected_historical_row_version integer,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())
returns jsonb language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_identity public.catalog_services%rowtype;v_source public.catalog_service_versions%rowtype;v_parent public.catalog_subcategories%rowtype;v_org uuid;v_hash text;v_command uuid;v_replay jsonb;v_number integer;v_version uuid;v_content_hash text;v_old_link record;v_link public.catalog_service_subcategory_links%rowtype;v_link_number integer;v_link_version uuid;v_link_hash text;v_response jsonb;v_fulfillment jsonb;v_visibility jsonb;
