 perform private.assert_catalog_central_aal2_locked(v_actor);select * into v_identity from public.catalog_services where id=p_service_id;if not found then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_APPROVE',v_actor);select * into v_source from public.catalog_service_versions where id=p_historical_version_id and service_id=p_service_id;if not found then raise exception 'CATALOG_VERSION_NOT_FOUND' using errcode='P0002';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.service.restore.v1','service_id',p_service_id,'historical_version_id',p_historical_version_id,'expected_identity',p_expected_identity_row_version,'expected_historical',p_expected_historical_row_version,'change_reason',btrim(p_change_reason)));select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.service.restore',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-service:'||p_service_id::text,0));select * into v_identity from public.catalog_services where id=p_service_id for update;perform private.assert_catalog_central_aal2_locked(v_actor);perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_APPROVE',v_actor);select * into v_source from public.catalog_service_versions where id=p_historical_version_id and service_id=p_service_id for share;if v_replay is not null then return v_replay;end if;
 if v_identity.row_version is distinct from p_expected_identity_row_version or v_source.row_version is distinct from p_expected_historical_row_version then raise exception 'STALE_CATALOG_VERSION' using errcode='40001';end if;if v_source.status not in ('APPROVED','PUBLISHED','RETIRED','ARCHIVED') then raise exception 'CATALOG_VERSION_NOT_HISTORICAL' using errcode='55000';end if;
