 values(p_service_id,v_identity.library_id,v_number,'DRAFT',v_source.name_fr,v_source.name_ar,v_source.short_description_fr,v_source.short_description_ar,v_source.long_description_fr,v_source.long_description_ar,v_source.service_type,v_source.unit_label_fr,v_source.unit_label_ar,v_source.credit_eligible,v_source.volume_eligible,v_source.recurring_eligible,v_source.trial_eligible,v_source.rfq_required,v_source.fixed_fulfillment_allowed,v_source.base_currency,v_source.sort_order,v_fulfillment,v_visibility,btrim(p_change_reason),v_content_hash,v_source.sensitive,'PENDING',v_actor,v_source.primary_subcategory_id,v_source.code,v_source.slug) returning id into v_version;
