 select * into v_link from public.catalog_service_subcategory_links where service_id=p_service_id and subcategory_id=v_source.primary_subcategory_id for update;v_link_hash:=private.canonical_request_hash(jsonb_build_object('service_id',p_service_id,'subcategory_id',v_source.primary_subcategory_id,'link_type','PRIMARY'));
 if found then select coalesce(max(version),0)+1 into v_link_number from public.catalog_service_subcategory_link_versions where link_id=v_link.id;insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_link.id,v_identity.library_id,v_link_number,'DRAFT',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,v_source.primary_subcategory_id,'PRIMARY') returning id into v_link_version;update public.catalog_service_subcategory_links set link_type='PRIMARY',status='DRAFT',current_version_id=v_link_version,row_version=row_version+1 where id=v_link.id;
 else insert into public.catalog_service_subcategory_links(service_id,subcategory_id,library_id,link_type,status,created_by) values(p_service_id,v_source.primary_subcategory_id,v_identity.library_id,'PRIMARY','DRAFT',v_actor) returning id into v_link.id;insert into public.catalog_service_subcategory_link_versions(link_id,library_id,version,status,change_reason,content_hash,created_by,service_id,subcategory_id,link_type) values(v_link.id,v_identity.library_id,1,'DRAFT',btrim(p_change_reason),v_link_hash,v_actor,p_service_id,v_source.primary_subcategory_id,'PRIMARY') returning id into v_link_version;update public.catalog_service_subcategory_links set current_version_id=v_link_version where id=v_link.id;end if;
 update public.catalog_services set primary_subcategory_id=v_source.primary_subcategory_id,code=v_source.code,slug=v_source.slug,status='DRAFT',current_draft_version_id=v_version,archived_at=null,row_version=row_version+1 where id=p_service_id;
 v_response:=jsonb_build_object('outcome','CATALOG_SERVICE_VERSION_RESTORED','service_id',p_service_id,'library_id',v_identity.library_id,'restored_from_version_id',p_historical_version_id,'version_id',v_version,'identity_row_version',p_expected_identity_row_version+1,'version_row_version',1,'content_hash',v_content_hash,'command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash) values(v_org,v_actor,'USER','catalog.service.version_restored','catalog_service',p_service_id::text,p_correlation_id,jsonb_build_object('historical_version_id',p_historical_version_id,'version_id',v_version,'command_id',v_command),v_source.content_hash,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,causation_id) values(v_org,'catalog_service',p_service_id::text,'CatalogServiceVersionRestoredV1',p_correlation_id,jsonb_build_object('service_id',p_service_id,'restored_from_version_id',p_historical_version_id,'version_id',v_version),p_idempotency_key,v_command);perform private.finish_catalog_command(v_actor,'catalog.service.restore',p_idempotency_key,v_response);return v_response;
end $$;

